<template>
  <div class="xiaoye-page">
    <header><div class="brand"><b>四</b><div><strong>四叶酒馆</strong><small>小叶工作台</small></div></div><div class="header-state"><el-tag v-if="tenantKey" type="info" effect="plain">租户：{{ tenantKey }}</el-tag><el-tag :type="ready ? 'success' : 'warning'">{{ ready ? '在线' : '检查中' }}</el-tag></div></header>
    <main>
      <aside><div v-if="approvals.length" class="approval-box"><strong>待审批 {{ approvals.length }}</strong><div v-for="row in approvals.slice(0,2)" :key="row.id" class="approval-mini"><span>{{ row.taskKey || row.approvalType || '待处理事项' }}</span><span><el-button link type="success" size="small" @click="approve(row)">批准</el-button><el-button link type="danger" size="small" @click="reject(row)">驳回</el-button></span></div></div><div class="side-head"><div><h3>小叶</h3><p>四叶酒馆智能体</p></div><el-button size="small" plain @click="newConversation">新对话</el-button></div><div class="conversation-list"><button v-for="item in conversations" :key="item.id || item.sessionId" :class="{active:(item.id||item.sessionId)===conversationId}" @click="openConversation(item)">{{ item.title || item.name || '小叶对话' }}</button><span v-if="!conversations.length" class="empty-side">暂无历史对话</span></div><div class="hint">可协助创作角色卡、世界书、任务规划和平台数据查询。</div></aside>
      <section class="chat"><div class="chat-head"><h2>小叶</h2><span>中文工作台</span></div><div ref="box" class="messages"><div v-if="!messages.length" class="welcome"><b>叶</b><h3>你好，我是小叶</h3><p>告诉我你想完成什么，我会先给出草稿和预览。</p><el-button plain @click="startRoleCard">帮我写一张角色卡</el-button></div><div v-for="m in messages" :key="m.id" class="message" :class="m.role"><i>{{ m.role === 'user' ? '我' : '叶' }}</i><div class="message-body" v-html="renderMessage(m.text)"></div><small v-if="m.pending" class="pending-label">处理中</small></div></div><div class="composer"><el-input v-model="draft" type="textarea" :rows="3" placeholder="告诉小叶你想完成什么……" @keydown.enter.exact.prevent="send"/><div class="send-row"><small>写入和高风险操作会先展示预览并等待确认</small><el-button type="primary" :loading="sending" @click="send">发送</el-button></div></div></section>
      <aside class="work"><el-tabs v-model="tab"><el-tab-pane label="角色卡" name="role"><div class="tab-title">小叶生成的草稿，保存前可继续修改</div><el-form label-position="top" size="small"><el-form-item label="名称"><el-input v-model="card.name"/></el-form-item><el-form-item label="标语"><el-input v-model="card.tagline"/></el-form-item><el-form-item label="简介"><el-input v-model="card.bio" type="textarea" :rows="3"/></el-form-item><el-form-item label="人设"><el-input v-model="card.persona" type="textarea" :rows="4"/></el-form-item><el-form-item label="背景与场景"><el-input v-model="card.scenario" type="textarea" :rows="3"/></el-form-item><el-form-item label="首条消息"><el-input v-model="card.firstMessage" type="textarea" :rows="3"/></el-form-item><el-form-item label="示例对话"><el-input v-model="card.mesExample" type="textarea" :rows="4"/></el-form-item><el-form-item label="系统提示词"><el-input v-model="card.systemPrompt" type="textarea" :rows="4"/></el-form-item><el-form-item label="历史消息指令"><el-input v-model="card.postHistoryInstructions" type="textarea" :rows="3"/></el-form-item><el-form-item label="创作者备注"><el-input v-model="card.creatorNotes" type="textarea" :rows="3"/></el-form-item><el-form-item label="头像提示词"><el-input v-model="card.visualPrompt" type="textarea" :rows="2"/></el-form-item><el-form-item label="头像负面提示词"><el-input v-model="card.visualNegativePrompt" type="textarea" :rows="2"/></el-form-item><el-form-item label="标签（JSON 数组）"><el-input v-model="card.tagsJson" placeholder='["吸血鬼","奇幻"]'/></el-form-item><el-form-item label="世界书条目（JSON 数组）"><el-input v-model="card.worldbookJson" type="textarea" :rows="4" placeholder='[{"key":"城堡","content":"..."}]'/></el-form-item></el-form><div class="action-row"><el-button type="primary" :loading="saving" :disabled="!card.name" @click="saveCard">校验并保存角色卡</el-button><el-button plain :disabled="!card.name" @click="saveWorldbook">保存世界书</el-button></div></el-tab-pane><el-tab-pane label="平台数据" name="data"><div class="stats"><b>任务总数：{{ overview.totalTasks || 0 }}</b><b>运行中：{{ overview.runningTasks || 0 }}</b><b>待审批：{{ overview.pendingApprovals || 0 }}</b><b>可用产物：{{ overview.readyArtifacts || 0 }}</b><b>已启用工具：{{ tools.length }}</b><b>可用世界书：{{ worldbooks.length }}</b><b>角色卡：{{ characters.length }}</b></div><div v-if="tools.length || agentRoles.length" class="capability-summary"><span v-for="item in tools.slice(0,8)" :key="item.id || item.toolKey">{{ item.name || item.toolName || item.toolKey || '工具' }}</span><span v-for="item in agentRoles.slice(0,4)" :key="item.id || item.roleKey">{{ item.displayName || item.name || item.roleKey || 'Agent 角色' }}</span></div><div class="data-section"><h4>四叶酒馆角色库</h4><div v-for="row in characters.slice(0,6)" :key="row.id" class="data-row"><span>{{ row.name || '未命名角色卡' }}</span><el-tag size="small" type="info">{{ row.gameplayType || '角色卡' }}</el-tag></div><el-empty v-if="!characters.length" description="暂无角色卡" :image-size="42"/><h4>最近任务</h4><div v-for="row in tasks" :key="row.id" class="data-row task-row" @click="openTask(row)"><span>{{ row.title || row.taskKey || '未命名任务' }}</span><el-tag size="small">{{ displayStatus(row.status) }}</el-tag></div><el-empty v-if="!tasks.length" description="暂无任务" :image-size="42"/></div></el-tab-pane><el-tab-pane label="执行" name="execution"><div v-if="selectedTask.id"><el-descriptions :column="1" border size="small"><el-descriptions-item label="任务">{{ selectedTask.title || selectedTask.taskKey || '-' }}</el-descriptions-item><el-descriptions-item label="状态">{{ displayStatus(selectedTask.status) }}</el-descriptions-item></el-descriptions><h4 class="section-heading">步骤</h4><div v-for="row in selectedTask.steps || []" :key="row.id || row.stepKey" class="data-row"><span>{{ row.stepName || row.stepKey || '步骤' }}</span><el-tag size="small">{{ displayStatus(row.status) }}</el-tag></div><h4 class="section-heading">工具调用</h4><div v-for="row in selectedTask.toolCalls || []" :key="row.id || row.callId" class="data-row"><span>{{ row.toolName || row.name || '工具' }}</span><el-tag size="small" :type="row.status === 'FAILED' ? 'danger' : 'success'">{{ displayStatus(row.status) }}</el-tag></div><h4 class="section-heading">产物</h4><div v-for="row in selectedTask.artifacts || []" :key="row.id || row.artifactKey" class="data-row"><span>{{ row.name || row.artifactKey || '产物' }}</span><el-button link type="primary" size="small" @click="downloadArtifact(row)">下载</el-button></div></div><el-empty v-else description="点击平台数据中的任务查看执行详情" :image-size="48"/></el-tab-pane><el-tab-pane label="审批" name="approval"><div v-for="row in approvals" :key="row.id" class="data-row"><span>{{ row.taskKey || row.approvalType || '待处理事项' }}</span><el-tag size="small" type="warning">待确认</el-tag></div><el-empty v-if="!approvals.length" description="暂无待审批事项" :image-size="42"/></el-tab-pane><el-tab-pane label="运行" name="runtime"><el-descriptions :column="1" border size="small"><el-descriptions-item label="服务">{{ runtime.service || '-' }}</el-descriptions-item><el-descriptions-item label="最近检查">{{ runtime.checkedAt ? new Date(runtime.checkedAt).toLocaleString() : '-' }}</el-descriptions-item><el-descriptions-item label="队列运行中">{{ runtime.queue?.runningTasks?.length || 0 }}</el-descriptions-item></el-descriptions></el-tab-pane></el-tabs></aside>
    </main>
  </div>
</template>
<script setup name="XiaoyeWorkspace">
import { getXiaoyeBootstrap, createXiaoyeConversation, listXiaoyeConversations, sendXiaoyeMessage, listXiaoyeMessages, validateXiaoyeRoleCard, createXiaoyeRoleCardDraft, saveXiaoyeRoleCardDraft, saveXiaoyeWorldbook, getXiaoyeTask, downloadXiaoyeArtifact, approveXiaoyeApproval, rejectXiaoyeApproval } from '@/api/jiugai/xiaoye'
import { ElMessage, ElMessageBox } from 'element-plus'
const ready=ref(false); const draft=ref(''); const sending=ref(false); const saving=ref(false); const tenantKey=ref(''); const conversationId=ref(''); const conversations=ref([]); const messages=ref([]); const overview=ref({}); const runtime=ref({}); const tasks=ref([]); const approvals=ref([]); const tools=ref([]); const agentRoles=ref([]); const worldbooks=ref([]); const characters=ref([]); const budget=ref({}); const selectedTask=ref({}); const tab=ref('role'); const box=ref()
const card=reactive({name:'',tagline:'',bio:'',persona:'',scenario:'',firstMessage:'',mesExample:'',systemPrompt:'',postHistoryInstructions:'',creatorNotes:'',visualPrompt:'',visualNegativePrompt:'',tagsJson:'[]',worldbookJson:'[]',stWorldNames:[]})
async function load(){try{const r=await getXiaoyeBootstrap();const bootstrap=r.data||{};tenantKey.value=bootstrap.tenantKey||'';overview.value=bootstrap.overview||{};runtime.value=bootstrap.runtime||{};tools.value=Array.isArray(bootstrap.tools)?bootstrap.tools:[];agentRoles.value=Array.isArray(bootstrap.agentRoles)?bootstrap.agentRoles:[];worldbooks.value=Array.isArray(bootstrap.worldbooks)?bootstrap.worldbooks:[];characters.value=Array.isArray(bootstrap.characters)?bootstrap.characters:[];budget.value=bootstrap.budget||{};tasks.value=Array.isArray(bootstrap.recentTasks)?bootstrap.recentTasks:[];approvals.value=Array.isArray(bootstrap.pendingApprovals)?bootstrap.pendingApprovals:[];ready.value=true;const conversationResult=await Promise.allSettled([listXiaoyeConversations()]);if(conversationResult[0].status==='fulfilled'){const value=conversationResult[0].value.data?.items||conversationResult[0].value.data?.sessions||[];conversations.value=Array.isArray(value)?value:[]}}catch{ready.value=false}}
async function ensure(){if(conversationId.value)return;const r=await createXiaoyeConversation({preset:'xiaoye'});conversationId.value=r.data?.conversationId||r.data?.session?.sessionId||r.data?.session?.id||''}
function text(v){if(!v)return '';if(typeof v==='string')return v;if(Array.isArray(v))return v.map(text).filter(Boolean).join('\n');if(typeof v==='object')return text(v.text||v.content||v.message||v.value||v.response||v.data)}
function displayStatus(value){const map={PENDING:'待处理',QUEUED:'排队中',RUNNING:'运行中',PAUSED:'已暂停',SUCCEEDED:'已完成',SUCCESS:'已完成',FAILED:'失败',CANCELLED:'已取消',CANCELED:'已取消',WAITING_APPROVAL:'待审批',RETRYING:'重试中'};return map[String(value||'').toUpperCase()]||value||'-'}
function renderMessage(value){let html=String(value||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');html=html.replace(/```([\s\S]*?)```/g,(_,code)=>`<pre><code>${code.trim()}</code></pre>`);html=html.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/^### (.+)$/gm,'<h4>$1</h4>').replace(/^## (.+)$/gm,'<h3>$1</h3>').replace(/^# (.+)$/gm,'<h2>$1</h2>').replace(/\n/g,'<br>');return html}
async function loadHistory(){if(!conversationId.value)return;try{const r=await listXiaoyeMessages(conversationId.value);const rows=r.data?.items||r.data?.events||r.data?.messages||[];const parsed=rows.map((row,index)=>{const item=row.event||row;const role=item.role||item.message?.role||(item.type==='user'?'user':'assistant');const value=text(item.content||item.message||item.text||item.data);return value?{id:`history-${index}`,role:role==='user'?'user':'assistant',text:value}:null}).filter(Boolean);if(parsed.length)messages.value=parsed}catch{}}
function parse(v){const m=String(v||'').match(/```json\s*([\s\S]*?)```/i);if(!m)return;try{const d=JSON.parse(m[1]);const direct=['name','tagline','bio','persona','scenario','firstMessage','mesExample','systemPrompt','postHistoryInstructions','creatorNotes','visualPrompt','visualNegativePrompt'];direct.forEach(k=>{if(typeof d[k]==='string')card[k]=d[k]});if(Array.isArray(d.tags))card.tagsJson=JSON.stringify(d.tags,null,2);if(Array.isArray(d.worldbookEntries))card.worldbookJson=JSON.stringify(d.worldbookEntries,null,2);tab.value='role'}catch{}}
async function waitForReply(previousCount){for(let i=0;i<24;i++){await new Promise(resolve=>setTimeout(resolve,1000));await loadHistory();const assistantCount=messages.value.filter(item=>item.role==='assistant').length;if(assistantCount>previousCount)return messages.value[messages.value.length-1]?.text||''}return ''}
async function send(){const value=draft.value.trim();if(!value||sending.value)return;draft.value='';messages.value.push({id:Date.now(),role:'user',text:value});const previousCount=messages.value.filter(item=>item.role==='assistant').length;messages.value.push({id:`pending-${Date.now()}`,role:'assistant',text:'小叶正在整理结果……',pending:true});sending.value=true;try{await ensure();await sendXiaoyeMessage(conversationId.value,value);const out=await waitForReply(previousCount);messages.value=messages.value.filter(item=>!item.pending);if(out)parse(out);else messages.value.push({id:Date.now()+1,role:'assistant',text:'请求已提交，但当前模型尚未返回最终内容。请稍后刷新会话。'})}catch(e){messages.value=messages.value.filter(item=>!item.pending);messages.value.push({id:Date.now()+1,role:'assistant',text:e?.message||'暂时无法连接小叶'})}finally{sending.value=false;nextTick(()=>{if(box.value)box.value.scrollTop=box.value.scrollHeight})}}
function startRoleCard(){draft.value='请帮我创作一张角色卡，先询问必要信息，再输出完整 JSON 草稿，不要直接保存。'}
function newConversation(){conversationId.value='';messages.value=[]}
async function openConversation(item){conversationId.value=item.id||item.sessionId||'';messages.value=[];await loadHistory()}
async function openTask(row){if(!row.id)return;tab.value='execution';try{const r=await getXiaoyeTask(row.id);selectedTask.value={...(r.data||{}),steps:r.steps||[],toolCalls:r.toolCalls||[],artifacts:r.artifacts||[]}}catch{selectedTask.value=row}}
async function downloadArtifact(row){const taskId=selectedTask.value.id;const key=row.artifactKey||row.key;if(!taskId||!key)return;try{const response=await downloadXiaoyeArtifact(taskId,key);const blob=response instanceof Blob?response:response.data;if(!blob)throw new Error('产物内容为空');const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=row.name||key;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000);ElMessage.success('产物下载已开始')}catch(e){ElMessage.error(e?.message||'产物下载失败')}}
async function approve(row){try{await approveXiaoyeApproval(row.id,{});ElMessage.success('已批准');await load()}catch(e){ElMessage.error(e?.message||'批准失败')}}
async function reject(row){try{await rejectXiaoyeApproval(row.id,{reason:'管理员在小叶工作台驳回'});ElMessage.success('已驳回');await load()}catch(e){ElMessage.error(e?.message||'驳回失败')}}
async function saveCard(){saving.value=true;try{const tags=JSON.parse(card.tagsJson||'[]');const worldbookEntries=JSON.parse(card.worldbookJson||'[]');if(!Array.isArray(tags)||!Array.isArray(worldbookEntries))throw new Error('标签和世界书必须是 JSON 数组');const payload={...card,tagsJson:JSON.stringify(tags),worldbookJson:JSON.stringify(worldbookEntries),stWorldNames:worldbookEntries.map(item=>item.name||item.key).filter(Boolean),confirmed:false};await validateXiaoyeRoleCard(payload);const draftResult=await createXiaoyeRoleCardDraft(payload);const draftId=draftResult.data?.draftId;if(!draftId)throw new Error('角色卡草稿创建失败');await ElMessageBox.confirm('校验已通过。确认将这张角色卡写入四叶酒馆角色库吗？','确认保存角色卡',{type:'warning',confirmButtonText:'确认保存',cancelButtonText:'继续编辑'});await saveXiaoyeRoleCardDraft(draftId);ElMessage.success('角色卡已保存到四叶酒馆角色库')}catch(e){const action=e?.action||e;if(action!=='cancel'&&action!=='close')ElMessage.error(e?.message||'保存失败')}finally{saving.value=false}}
async function saveWorldbook(){try{const entries=JSON.parse(card.worldbookJson||'[]');if(!Array.isArray(entries)||!entries.length)throw new Error('请先填写世界书条目');await ElMessageBox.confirm('确认将这些世界书条目写入四叶酒馆吗？','确认保存世界书',{type:'warning',confirmButtonText:'确认保存',cancelButtonText:'继续编辑'});await saveXiaoyeWorldbook({name:card.name+'设定',entries,confirmed:true});ElMessage.success('世界书已保存')}catch(e){const action=e?.action||e;if(action!=='cancel'&&action!=='close')ElMessage.error(e?.message||'世界书保存失败')}}
onMounted(load)
</script>
<style scoped>
.xiaoye-page{min-height:calc(100vh - 84px);background:#f4f7f3;color:#26352a}.xiaoye-page header{height:68px;padding:0 24px;background:#fff;border-bottom:1px solid #dfe9df;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center}.brand b,.welcome>b,.message i{display:grid;place-items:center;border-radius:50%;background:#4a8d60;color:#fff}.brand b{width:34px;height:34px}.brand strong,.brand small{display:block}.brand small{font-size:12px;color:#829083}main{display:grid;grid-template-columns:250px minmax(420px,1fr) 390px;height:calc(100vh - 84px)}aside,.work{padding:20px;background:#fff;border-right:1px solid #dfe9df}.work{border-right:0;border-left:1px solid #dfe9df;overflow:auto}.side-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}.side-head h3{margin:0}.side-head p,aside p,aside .hint{font-size:12px;color:#829083;line-height:1.6}.conversation-list{display:grid;gap:5px;margin-top:20px}.conversation-list button{border:0;border-radius:7px;padding:10px;text-align:left;background:#f7faf7;color:#536456;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.conversation-list button.active{background:#e5f2e7;color:#315d3b;font-weight:600}.empty-side{padding:8px;color:#a0aaa1;font-size:12px}.hint{margin-top:20px}.chat{display:flex;flex-direction:column;min-width:0}.chat-head{padding:18px 24px;background:#fff;border-bottom:1px solid #dfe9df}.chat-head h2{margin:0}.chat-head span{font-size:12px;color:#829083}.messages{flex:1;overflow:auto;padding:28px 8%}.welcome{text-align:center;margin:14vh auto;color:#829083}.welcome>b{width:52px;height:52px;margin:auto;font-size:22px}.welcome h3{color:#26352a}.message{display:flex;gap:10px;margin-bottom:18px;line-height:1.7}.message.user{flex-direction:row-reverse}.message i{width:30px;height:30px;flex:0 0 30px;font-style:normal;font-size:12px}.message>div{max-width:78%;padding:11px 14px;background:#fff;border-radius:9px;white-space:pre-wrap}.message.user>div{background:#e5f2e7}.composer{padding:14px 8%;background:#fff;border-top:1px solid #dfe9df}.send-row{display:flex;justify-content:space-between;align-items:center;margin-top:8px}.send-row small{color:#94a296;font-size:11px}.stats{display:grid;gap:12px}.stats b{padding:14px;border:1px solid #dfe9df;border-radius:7px;color:#477152}.tab-title{margin:-4px 0 14px;color:#829083;font-size:12px}.data-section{margin-top:20px}.data-section h4,.section-heading{margin:16px 0 8px;font-size:13px}.data-row{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid #edf2ed;font-size:12px}.data-row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-row{cursor:pointer}.task-row:hover{background:#f5faf5}@media(max-width:1000px){main{grid-template-columns:190px minmax(360px,1fr)}.work{display:none}}@media(max-width:680px){main{display:block}.chat{height:calc(100vh - 84px)}main>aside{display:none}.messages,.composer{padding-left:16px;padding-right:16px}}
.approval-box{margin-bottom:16px;padding:10px;border:1px solid #f0d9a8;border-radius:7px;background:#fff9ed;color:#755514;font-size:12px}.approval-mini{display:flex;align-items:center;justify-content:space-between;gap:5px;margin-top:8px;padding-top:8px;border-top:1px solid #f5e6c8}.approval-mini>span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stats b{padding:12px;font-size:12px}.capability-summary{display:flex;flex-wrap:wrap;gap:6px;margin-top:16px}.capability-summary span{padding:5px 8px;border-radius:999px;background:#eef7ef;color:#477152;font-size:11px}
/* 四叶酒馆工作台：纸张、墨色和琥珀色点缀，保持高密度但不压迫。 */
.xiaoye-page{--ink:#21312a;--muted:#748277;--line:#dce5dc;--leaf:#357554;--amber:#b7803e;background:#edf1ec;font-family:"Noto Sans SC","Microsoft YaHei",sans-serif}.xiaoye-page header{background:#fbfcf9;box-shadow:0 1px 12px rgba(31,54,39,.06)}.brand b{background:var(--leaf);box-shadow:0 4px 10px rgba(53,117,84,.2);font-family:Georgia,serif}.brand strong,.chat-head h2,.side-head h3{color:var(--ink);letter-spacing:.02em}.brand small{color:var(--amber);font-weight:600}.chat-head{background:#fbfcf9}.chat-head h2{font-family:Georgia,"Noto Serif SC",serif;font-size:22px}.messages{background:radial-gradient(circle at 50% 0,rgba(255,255,255,.8),transparent 52%)}.welcome{animation:welcome-in .45s ease-out both}.welcome h3{font-family:Georgia,"Noto Serif SC",serif;font-size:24px}.message>div{box-shadow:0 5px 18px rgba(35,54,42,.05);border:1px solid rgba(220,229,220,.8)}.message.user>div{border-color:#c8dfcc;box-shadow:none}.composer{background:#fbfcf9}.composer :deep(.el-textarea__inner){border-color:#cad8cb;box-shadow:inset 0 1px 2px rgba(25,53,35,.03);transition:border-color .2s,box-shadow .2s}.composer :deep(.el-textarea__inner:focus){border-color:var(--leaf);box-shadow:0 0 0 3px rgba(53,117,84,.12)}.work{background:#fbfcf9}.work :deep(.el-tabs__item.is-active){color:var(--leaf);font-weight:700}.work :deep(.el-tabs__active-bar){background:var(--amber)}.work :deep(.el-form-item__label){color:#536359;font-weight:600}.work :deep(.el-input__wrapper),.work :deep(.el-textarea__inner){border-color:#d6e1d6}.work :deep(.el-input__wrapper.is-focus),.work :deep(.el-textarea__inner:focus){box-shadow:0 0 0 1px var(--leaf) inset}.conversation-list button{border:1px solid transparent;transition:background .18s,border-color .18s,transform .18s}.conversation-list button:hover{background:#eef6ef;border-color:#d3e4d5;transform:translateX(2px)}.conversation-list button.active{border-color:#c4dcc8}.stats b{background:#f6faf6}.capability-summary span{border:1px solid #d8eadb}.data-row{transition:background .16s}.task-row:hover{background:#f0f7f1}.action-row{display:flex;gap:8px;position:sticky;bottom:-20px;padding:12px 0 4px;background:#fbfcf9}.approval-box{box-shadow:0 5px 14px rgba(115,83,28,.08)}@keyframes welcome-in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@media(max-width:680px){.xiaoye-page main{display:flex;flex-direction:column;height:auto}.xiaoye-page main>aside:first-child{display:none}.xiaoye-page .chat{height:65vh;min-height:520px}.xiaoye-page main>aside.work{display:block;height:52vh;border-top:1px solid var(--line);border-left:0;overflow:auto}.xiaoye-page .messages{padding:20px 16px}.xiaoye-page .composer{padding:12px 16px}.xiaoye-page .action-row{bottom:-20px}}
